/// <summary>
/// Validation class for inbound container incl sub directories
/// </summary>
class OMGAzureValidator_InboundContainerSubDir extends OMGAzureValidator_InboundContainer
{
}

Method.Source:
/// <summary>
/// Validates the archiving parameters
/// </summary>
/// <returns>True if all ok</returns>
public boolean validateArchiving()
{                
    OMGInboundDataContract_AzureContainerSubDir     inboundDataContract = this.parmDataContract();
    boolean                                         ret = true;
    ;

    if (inboundDataContract.parmArchiveUnderSubDir() == NoYes::No)
    {
        ret = super();
    }
    else if (!inboundDataContract.parmArchiveContainerName())
    {
        ret = checkFailed("@OMG:ArchiveNameMissing");
    }        

    return ret;
}
